package com.example.yuejie;
import android.app.*;import android.os.*;import android.text.*;import android.graphics.*;import org.json.*;import java.util.*;import java.io.*;
/** Differential oracle: fixtures are original TTText results, never Android line-break output. */
public class TypographyChecks extends Instrumentation {
 int paragraphs,lines,breaks,geometry;float maxDrift;JSONArray failures=new JSONArray();
 public void onCreate(Bundle b){start();}
 String read(String name)throws Exception{try(InputStream in=getTargetContext().getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];for(int n;(n=in.read(b))>=0;)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}}
 int start(JSONObject r)throws Exception{return r.getJSONObject("fields").getInt("location");}
 void failure(String kind,int font,String expected,String actual)throws Exception{int count=0;for(int i=0;i<failures.length();i++)if(failures.getJSONObject(i).getString("kind").equals(kind))count++;if(count<15)failures.put(new JSONObject().put("kind",kind).put("font",font).put("expected",expected).put("actual",actual));}
 void fixture(String name)throws Exception{
  JSONObject fixture=new JSONObject(read(name)),config=fixture.getJSONObject("layout").getJSONObject("c");int font=fixture.getJSONObject("config").getInt("b0")/3;
  JSONArray paras=fixture.getJSONArray("paragraphs"),pages=fixture.getJSONArray("pages");Map<Integer,List<JSONObject>> expected=new HashMap<>();
  for(int p=0;p<pages.length();p++){JSONObject page=pages.getJSONObject(p);int pageStart=start(page.getJSONObject("range"));JSONArray rows=page.getJSONArray("lines");for(int r=0;r<rows.length();r++){JSONObject row=rows.getJSONObject(r);int at=pageStart+start(row.getJSONObject("range"));for(int n=0;n<paras.length();n++){JSONObject para=paras.getJSONObject(n);int a=start(para.getJSONObject("range"));if(a<=at&&at<a+para.getString("text").length()){if(!expected.containsKey(n))expected.put(n,new ArrayList<>());expected.get(n).add(row);break;}}}}
  for(int n=0;n<paras.length();n++){
   JSONObject para=paras.getJSONObject(n);String text=para.getString("text");if(text.endsWith("\n"))text=text.substring(0,text.length()-1);
   TextPaint paint=new TextPaint(3);paint.setTypeface(Typeface.createFromAsset(getTargetContext().getAssets(),fixture.getString("referenceFont")));paint.setTextSize((float)config.getDouble(n==0?"titleFontSize":"textFontSize"));paint.setFakeBoldText(n==0);if(n==0)paint.setTextSize(ReaderTextLayout.headingSize((float)config.getDouble("textFontSize"),(float)config.getDouble("titleFontSize"),3));
   JSONObject inline=fixture.optJSONObject("inlineDelegates"),delegate=inline==null?null:inline.optJSONObject(Integer.toString(n));float bubble=delegate==null?0:(float)(delegate.getJSONObject("delegate").getDouble("g")+delegate.getJSONObject("delegate").getDouble("e"));
   ReaderTextLayout layout=new ReaderTextLayout(text,paint,config.getInt("width"),n==0?paint.getTextSize()*.5f:(float)config.getDouble("lineSpace"),n==0,bubble);
   List<JSONObject> rows=expected.get(n);if(rows==null&&text.isEmpty())rows=Collections.emptyList();if(rows==null)throw new AssertionError("missing reference paragraph");paragraphs++;
   if(layout.getLineCount()!=rows.size()){breaks++;failure("line-count",font,Integer.toString(rows.size()),Integer.toString(layout.getLineCount()));}
   for(int l=0;l<Math.min(layout.getLineCount(),rows.size());l++){
    ReaderTextLayout.Line line=layout.lines.get(l);JSONObject row=rows.get(l);String want=row.getString("text");if(want.endsWith("\n"))want=want.substring(0,want.length()-1);String actual=text.substring(line.start,line.end);lines++;
    if(!want.equals(actual)){breaks++;failure("line-text",font,want,actual);continue;}
    JSONArray rects=row.getJSONArray("chars");for(int i=line.first;i<line.last;i++){int index=layout.clusters.get(i).start-line.start;JSONArray rect=rects.getJSONArray(index);float dx=Math.abs(line.x[i-line.first]-(float)rect.getDouble(0)),dw=Math.abs(line.widths[i-line.first]-(float)(rect.getDouble(2)-rect.getDouble(0)));float drift=Math.max(dx,dw);maxDrift=Math.max(maxDrift,drift);if(drift>1.01f){geometry++;failure("glyph-x",font,rect.toString(),"x="+line.x[i-line.first]+" width="+line.widths[i-line.first]+" text="+want);}}
   }
  }
  chapter(fixture,font,name);
 }
 int pageMismatches,verticalMismatches,bubbleMismatches;float maxY;JSONArray chapterReports=new JSONArray();
 int originalOffset(Map<Integer,Integer> map,int offset){int base=0;for(int at:map.keySet())if(at<=offset)base=at;else break;return map.get(base)+offset-base;}
 void chapter(JSONObject fixture,int font,String fixtureName)throws Exception{
  JSONArray paras=fixture.getJSONArray("paragraphs"),reference=fixture.getJSONArray("pages");StringBuilder body=new StringBuilder();Map<Integer,Long> counts=new HashMap<>();Map<Integer,Integer> nativeOffsets=new TreeMap<>();JSONObject delegates=fixture.getJSONObject("inlineDelegates");
  for(int n=1;n<paras.length();n++){if(n>1)body.append("\n\n");String value=paras.getJSONObject(n).getString("text");if(value.endsWith("\n"))value=value.substring(0,value.length()-1);nativeOffsets.put(body.length(),start(paras.getJSONObject(n).getJSONObject("range")));if(delegates.has(Integer.toString(n)))counts.put(body.length(),1L);body.append(value);}
  String title=paras.getJSONObject(0).getString("text");if(title.endsWith("\n"))title=title.substring(0,title.length()-1);
  ReaderSettings settings=new ReaderSettings(getTargetContext());settings.font=font;settings.legacyLineSpacing=true;settings.lineSpacing=ReaderSettings.legacySpacing(fixture.optInt("spacingSetting",1));settings.fontWeight=0;settings.serif=fixture.getString("referenceFont").contains("serif");settings.comments=true;
  ReaderPaginator paginator=new ReaderPaginator(body.toString(),title,1080,1920,3,3,settings,counts);
  if(paginator.pages.size()!=reference.length()){pageMismatches++;failure("page-count",font,""+reference.length(),""+paginator.pages.size());}
  JSONArray actualPages=new JSONArray();for(int p=0;p<Math.min(paginator.pages.size(),reference.length());p++){
   ReaderPaginator.Page page=paginator.pages.get(p);JSONObject wantPage=reference.getJSONObject(p);JSONArray rows=wantPage.getJSONArray("lines");List<String> texts=new ArrayList<>();List<Float> tops=new ArrayList<>();List<Integer> offsets=new ArrayList<>();
   int pageStart=p==0?0:originalOffset(nativeOffsets,page.start),pageEnd=page.end==body.length()?fixture.getString("text").length():originalOffset(nativeOffsets,page.end);JSONObject range=wantPage.getJSONObject("range").getJSONObject("fields");if(pageStart!=range.getInt("location")||pageEnd!=range.getInt("location")+range.getInt("length")){pageMismatches++;failure("page-range",font,range.toString(),pageStart+":"+pageEnd);}
   if(page.first)for(ReaderTextLayout.Line line:paginator.heading.lines){texts.add(title.substring(line.start,line.end));offsets.add(line.start);tops.add(line.top+paginator.heading.lineSpace/2);}
   for(ReaderPaginator.Fragment f:page.fragments)for(int l=f.firstLine;l<f.lastLine;l++){ReaderTextLayout.Line line=f.layout.lines.get(l);texts.add(f.layout.text.substring(line.start,line.end));offsets.add(originalOffset(nativeOffsets,f.paragraphStart+line.start));tops.add(f.y-paginator.top-f.layout.getLineTop(f.firstLine)+line.top+f.layout.lineSpace/2);}
   Set<Integer> expectedBubbles=new HashSet<>(),actualBubbles=new HashSet<>();JSONArray pageDelegates=wantPage.optJSONArray("delegates");if(pageDelegates!=null)for(int d=0;d<pageDelegates.length();d++)expectedBubbles.add(start(pageDelegates.getJSONObject(d).getJSONObject("originalRange")));for(ReaderPaginator.Fragment f:page.fragments)if(paginator.commentBubble(f)!=null){int paraIndex=-1;for(int n=1;n<paras.length();n++)if(start(paras.getJSONObject(n).getJSONObject("range"))==originalOffset(nativeOffsets,f.paragraphStart)){paraIndex=n;break;}if(paraIndex>=0){JSONObject source=paras.getJSONObject(paraIndex);JSONObject nativeRange=source.getJSONObject("range").getJSONObject("nativeFields");actualBubbles.add(nativeRange.getInt("location")+nativeRange.getInt("length"));}}if(!expectedBubbles.equals(actualBubbles)){bubbleMismatches++;failure("bubble-page",font,expectedBubbles.toString(),actualBubbles.toString());}
   actualPages.put(new JSONObject().put("page",p).put("start",pageStart).put("end",pageEnd).put("offsets",new JSONArray(offsets)).put("texts",new JSONArray(texts)).put("tops",new JSONArray(tops)));if(texts.size()!=rows.length()){pageMismatches++;failure("page-rows",font,"page="+p+" rows="+rows.length(),""+texts.size());}
   for(int l=0;l<Math.min(texts.size(),rows.length());l++){JSONObject row=rows.getJSONObject(l);String want=row.getString("text");if(want.endsWith("\n"))want=want.substring(0,want.length()-1);if(!texts.get(l).equals(want)||offsets.get(l)!=pageStart+start(row.getJSONObject("range"))){pageMismatches++;failure("page-line",font,want,texts.get(l));}float dy=Math.abs(tops.get(l)-(float)row.getJSONArray("rect").getDouble(1));maxY=Math.max(maxY,dy);if(dy>1){verticalMismatches++;failure("line-y",font,row.getJSONArray("rect").toString(),""+tops.get(l));}}
  }
  try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(getTargetContext().getFilesDir(),"typography-"+fixtureName)),"UTF-8")){out.write(actualPages.toString());}chapterReports.put(new JSONObject().put("font",font).put("family",fixture.getString("referenceFont")).put("expectedPages",reference.length()).put("actualPages",paginator.pages.size()));
 }
 public void onStart(){Bundle result=new Bundle();Throwable error=null;try{ReaderSettings.loadFonts(getTargetContext());JSONArray names=new JSONArray(read("index.json"));for(int i=0;i<names.length();i++)fixture(names.getString(i));if(breaks!=0||geometry!=0||pageMismatches!=0||verticalMismatches!=0||bubbleMismatches!=0)throw new AssertionError("breaks="+breaks+" glyphs="+geometry+" pages="+pageMismatches+" y="+verticalMismatches);result.putString("stream","PASS paragraphs="+paragraphs+" lines="+lines+" maxDrift="+maxDrift+"\n");}catch(Throwable t){error=t;result.putString("stream","FAIL "+android.util.Log.getStackTraceString(t));}
 try{JSONObject json=new JSONObject().put("success",error==null).put("paragraphs",paragraphs).put("lines",lines).put("breakMismatches",breaks).put("geometryMismatches",geometry).put("maxDrift",maxDrift).put("pageMismatches",pageMismatches).put("verticalMismatches",verticalMismatches).put("maxY",maxY).put("bubbleMismatches",bubbleMismatches).put("chapters",chapterReports).put("failures",failures);try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(getTargetContext().getFilesDir(),"typography.json")),"UTF-8")){out.write(json.toString(2));}}catch(Exception e){error=e;result.putString("stream",e.toString());}finish(error==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
